const mascot=`<svg viewBox="0 0 260 350" xmlns="http://www.w3.org/2000/svg" fill="none" aria-hidden="true"><path d="m91 281-9 36-24 1q-16 9-5 16h41l15-49m48-4 10 36 25 1q15 9 5 16h-41l-16-49" fill="#226b72"/><path d="M80 142q-31-1-43 24l-17-5" stroke="#e7a044" stroke-width="13" stroke-linecap="round"/><path d="m20 160-7-10m7 10-13 2" stroke="#e7a044" stroke-width="8" stroke-linecap="round"/><g class="wave-hand"><path d="M176 147q38 8 39-30l-1-14" stroke="#e7a044" stroke-width="13" stroke-linecap="round"/><path d="m213 105-11-9m11 9 1-18m0 18 12-12" stroke="#e7a044" stroke-width="8" stroke-linecap="round"/></g><g transform="rotate(-7 130 170)"><path d="m78 84 49-66 50 66v195q-46 25-99 0Z" fill="#ffc758" stroke="#cc9240" stroke-width="2"/><path d="m78 84 49-66 50 66" fill="#f5d5ac"/><path d="m111 40 16-22 17 22q-16 10-33 0Z" fill="#315a60"/><path d="M78 84h23v192l-23 3Z" fill="#edaa46"/><path d="M154 84h23v195l-23-4Z" fill="#f3b33e"/><path d="M78 263q49 19 99 0v22q-49 20-99 0Z" fill="#abd1ce"/><path d="M78 285q49 20 99 0v18q-5 18-49 18t-50-18Z" fill="#e68d9c"/><path d="M92 149v8m54-8v8" stroke="#335960" stroke-width="8" stroke-linecap="round"/><path d="M109 174q15 20 28-1" fill="#fff9df" stroke="#335960" stroke-width="3" stroke-linecap="round"/><ellipse cx="93" cy="175" rx="10" ry="6" fill="#ee9775"/><ellipse cx="153" cy="175" rx="10" ry="6" fill="#ee9775"/><path d="M110 98v25" stroke="#ffe7a0" stroke-width="7" stroke-linecap="round"/><path d="m91 198 38 12 37-12-11 25-28-6-27 7Z" fill="#228b8e"/><path d="m128 210 10 42 20-16-21-22" fill="#228b8e"/><circle cx="128" cy="211" r="8" fill="#17757b"/></g></svg>`;
document.querySelectorAll('[data-name]').forEach(e=>e.textContent=B.name);document.title=`${B.name} · Aprender es una aventura`;
document.querySelectorAll('[data-mascot]').forEach(e=>e.innerHTML=mascot);
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icons[e.dataset.icon]);
document.querySelectorAll('[data-address]').forEach(e=>e.textContent=B.address);
document.querySelector('.maps').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(B.address+', Perú');
document.querySelectorAll('[data-call]').forEach(e=>{e.textContent=B.displayPhone;e.href='tel:+'+B.phone});
const wa=message=>'https://wa.me/'+B.phone+'?text='+encodeURIComponent(message);
document.querySelectorAll('[data-wa]').forEach(e=>e.href=wa('Hola, quisiera consultar información sobre '+B.name+'.'));
const select=document.querySelector('#service');
[...B.programs,...B.workshops].forEach(p=>{const o=document.createElement('option');o.value=p.name;o.textContent=p.name;select.append(o)});
document.querySelector('#program-list').innerHTML=B.programs.map((p,i)=>`<article class="program ${p.color} reveal"><div class="program-visual"><span class="program-number">0${i+1}</span>${icons[p.icon]}</div><h3>${p.name}</h3><p>${p.text}</p><a href="#contacto" data-service="${p.name}">Consultar este programa <span aria-hidden="true">↗</span></a></article>`).join('');
const workshops=document.querySelector('#workshop-list');
workshops.innerHTML=B.workshops.map((p,i)=>`<button class="workshop reveal" style="--workshop:${p.color}" data-index="${i}" aria-pressed="${i===0}" aria-controls="workshop-description"><span class="plus" aria-hidden="true">${i===0?'−':'+'}</span>${icons[p.icon]}<strong>${p.name}</strong></button>`).join('');
function explore(i){const p=B.workshops[i];document.querySelector('#workshop-title').textContent=p.name;document.querySelector('#workshop-description').textContent=p.text;document.querySelector('.detail-number').textContent=`0${i+1} / EXPLORA`;document.querySelector('#workshop-query').dataset.service=p.name;workshops.querySelectorAll('button').forEach((e,j)=>{e.setAttribute('aria-pressed',String(i===j));e.querySelector('.plus').textContent=i===j?'−':'+';});}
explore(0);workshops.addEventListener('click',e=>{const b=e.target.closest('button');if(b)explore(Number(b.dataset.index))});
document.addEventListener('click',e=>{const link=e.target.closest('[data-service]');if(link){select.value=link.dataset.service;setTimeout(()=>document.querySelector('#parent-name').focus({preventScroll:true}),500)}});
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#parent-name');if(!name.value.trim()){name.setCustomValidity('Escribe tu nombre para preparar el mensaje.');name.reportValidity();return;}const message=`Hola, soy ${name.value.trim()}. Me interesa ${select.value}. Quisiera consultar edades, precios, horarios y disponibilidad.`;window.open(wa(message),'_blank','noopener,noreferrer')});
document.querySelector('#parent-name').addEventListener('input',e=>e.target.setCustomValidity(''));
document.querySelectorAll('.star').forEach(e=>e.addEventListener('click',()=>{e.classList.remove('pop');void e.offsetWidth;e.classList.add('pop')}));
const motion=document.querySelector('#motion'),preference=matchMedia('(prefers-reduced-motion: reduce)');let paused=preference.matches;try{paused=paused||localStorage.getItem('verano-motion')==='paused'}catch{}
function applyMotion(){document.body.classList.toggle('paused',paused);motion.setAttribute('aria-pressed',String(paused));motion.textContent=paused?'Activar animaciones':'Pausar animaciones'}applyMotion();
motion.addEventListener('click',()=>{paused=!paused;applyMotion();try{localStorage.setItem('verano-motion',paused?'paused':'active')}catch{}});
preference.addEventListener('change',e=>{paused=e.matches;applyMotion()});
if('IntersectionObserver' in window){document.body.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e))}
